{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C13"],
      "claim": "In healthy men, 11C-SCH 23390, the closest high-similarity analog sharing the 7-chloro-8-hydroxy-3-methyl-benzazepine core, showed rapid transfer into brain with 1.2% of injected radioactivity in brain at 4.5 min, demonstrating meaningful CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "The 4-iodophenyl analog [125I]FISCH showed good brain uptake in rats after iv injection (2.27% dose/whole brain at 2 min), directly supporting CNS penetration for this benzazepine scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "The 3-iodophenyl analog S-(-)-8 had good initial brain uptake in rats (1.59% dose/organ at 2 min), indicating that this structural family can pass the blood-brain barrier with ease.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "The related [123I]SCH 23982 showed a brain-to-blood ratio of about 1.2 at 10 min in rats, indicating active brain uptake and meaningful CNS exposure.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a close structural analog of SCH 23390 and related 1-aryl-3-benzazepines that consistently show rapid, meaningful brain uptake in humans and rodents. Direct PET, SPECT, biodistribution, and brain-to-plasma evidence from these high-transfer analogs supports CNS access; no contradictory evidence was retrieved.",
  "evidence_gaps": [
    "No direct experimental measurement for the exact query molecule.",
    "No explicit efflux-transporter data for the query or its closest analogues.",
    "The added dichlorodihydrobenzofuranyl group is bulkier than the phenyl/iodophenyl substituents in the evidence molecules, so its effect on permeability is inferred rather than directly measured."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

